from core.lib.third_party.snap_minis_sdk import SnapMinisSDKConnector
c = SnapMinisSDKConnector()
c.connect()
# In studio/dapp/server.py POST /dapp/api/snap_mini_event handler:
if not SnapMinisSDKConnector.verify_dapp_token(bearer_token):
    return 401
r = c.send('record_event', json.dumps({
    'event_name': 'mini.user.identified',
    'user_id':    request_json['user_id'],
    'signed_data': request_json.get('signed_data', ''),
    'payload':    request_json.get('payload', {}),
}))
return {'ok': r.success, 'crystal': r.crystal_id}
